/**
 * Localisation (v1.0): English is the source language. French translates the menus, HUD labels, tabs,
 * mentor tips, chapter text, achievements, parts, jobs and alarms. Switching the language reloads the
 * page, so the data tables are translated once at start-up (`applyLanguage`) and views call `t()`.
 * Messages generated by the simulation log (e.g. "Generator test passed") stay in English for now.
 */
export type Lang = 'en' | 'fr';
export const LANGS: Record<Lang, string> = { en: 'English', fr: 'Français' };

let current: Lang = 'en';
export const currentLang = (): Lang => current;

export function detectLang(preferred: readonly string[] | undefined): Lang {
  return (preferred ?? []).some((l) => l.toLowerCase().startsWith('fr')) ? 'fr' : 'en';
}

